<template>
  <aside class="assistant" :class="{ open }" aria-label="Assistant du portfolio">
    <button v-if="!open" class="assistant-fab" type="button" @click="open = true"><span>✦</span> ASSISTANT DE JUDE</button>
    <section v-else class="assistant-panel">
      <header><div><span>ASSISTANT DU PORTFOLIO</span><strong>Une question sur le parcours de Jude ?</strong></div><button type="button" @click="open = false" aria-label="Fermer l’assistant">×</button></header>
      <div ref="feed" class="assistant-feed"><div v-for="(message,index) in messages" :key="index" :class="['assistant-message', message.role === 'assistant' ? 'bot' : 'user']" v-html="renderMarkdown(message.text)"></div><p v-if="loading" class="assistant-message assistant-loading">Analyse du contexte…</p></div>
      <div class="quick-questions"><button v-for="question in quickQuestions" :key="question" type="button" :disabled="loading" @click="ask(question)">{{ question }}</button></div>
      <form @submit.prevent="ask(input)"><label class="sr-only" for="assistant-input">Votre question</label><input id="assistant-input" v-model="input" :disabled="loading" placeholder="Posez une question…"><button :disabled="loading || !input.trim()">↗</button></form>
    </section>
  </aside>
</template>
<script setup>
import { nextTick, ref } from 'vue'
const open = ref(false), input = ref(''), loading = ref(false), feed = ref(null)
// Assistant answers are generated server-side; the UI retains only this session's history.
const messages = ref([])
const quickQuestions = ['Présente-moi Jude', 'Quelles sont les compétences Data de Jude ?', 'Quels projets a-t-il réalisés ?', 'Où puis-je télécharger son CV ?', 'Comment le contacter ?']
const escapeHtml = value => value.replace(/[&<>'"]/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#039;', '"': '&quot;' })[character])
const inlineMarkdown = value => escapeHtml(value).replace(/`([^`]+)`/g, '<code>$1</code>').replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
function renderMarkdown(value) { const lines = String(value || '').replace(/\r/g, '').split('\n'); const output = []; let index = 0; while (index < lines.length) { const line = lines[index]; if (line.startsWith('```')) { const code = []; index++; while (index < lines.length && !lines[index].startsWith('```')) code.push(lines[index++]); output.push(`<pre><code>${escapeHtml(code.join('\n'))}</code></pre>`); index++; continue } if (/^#{1,3}\s+/.test(line)) { output.push(`<h4>${inlineMarkdown(line.replace(/^#{1,3}\s+/, ''))}</h4>`); index++; continue } if (/^[-*]\s+/.test(line)) { const items = []; while (index < lines.length && /^[-*]\s+/.test(lines[index])) items.push(`<li>${inlineMarkdown(lines[index++].replace(/^[-*]\s+/, ''))}</li>`); output.push(`<ul>${items.join('')}</ul>`); continue } if (/^\d+\.\s+/.test(line)) { const items = []; while (index < lines.length && /^\d+\.\s+/.test(lines[index])) items.push(`<li>${inlineMarkdown(lines[index++].replace(/^\d+\.\s+/, ''))}</li>`); output.push(`<ol>${items.join('')}</ol>`); continue } if (!line.trim()) { index++; continue } const paragraph = [line]; index++; while (index < lines.length && lines[index].trim() && !/^#{1,3}\s+|^[-*]\s+|^\d+\.\s+|^```/.test(lines[index])) paragraph.push(lines[index++]); output.push(`<p>${paragraph.map(inlineMarkdown).join('<br>')}</p>`) } return output.join('') }
async function ask(question) { const text = question.trim(); if (!text || loading.value) return; messages.value.push({ role: 'user', text }); input.value = ''; loading.value = true; await nextTick(); feed.value?.scrollTo({ top: feed.value.scrollHeight, behavior: 'smooth' }); try { const conversation = messages.value.map(message => ({ role: message.role, content: message.text })); const endpoint = '/.netlify/functions/portfolio-assistant'; console.info('[portfolio-assistant] request', { url: endpoint, method: 'POST', messages: conversation.length }); const response = await fetch(endpoint, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ messages: conversation }) }); const rawBody = await response.clone().text(); console.info('[portfolio-assistant] response', { url: endpoint, status: response.status, statusText: response.statusText, body: rawBody }); let data; try { data = JSON.parse(rawBody) } catch { throw new Error(`Invalid JSON response (${response.status}): ${rawBody.slice(0, 300)}`) } if (!response.ok || !data.answer) throw new Error(data.error || `Assistant unavailable (${response.status})`); messages.value.push({ role: 'assistant', text: data.answer }) } catch (error) { console.error('[portfolio-assistant] failed', error); messages.value.push({ role: 'assistant', text: 'Une erreur est survenue lors de la génération de la réponse. Veuillez réessayer.' }) } finally { loading.value = false; await nextTick(); feed.value?.scrollTo({ top: feed.value.scrollHeight, behavior: 'smooth' }) } }
</script>
<style scoped>
.assistant{position:fixed;right:22px;bottom:22px;z-index:40;font-family:'DM Mono',monospace}.assistant-fab{background:#e8b84b;color:#17150f;border:0;padding:13px 15px;font:500 10px 'DM Mono';letter-spacing:.05em;box-shadow:0 12px 35px #0007;transition:transform .2s}.assistant-fab:hover{transform:translateY(-3px)}.assistant-fab span{margin-right:7px}.assistant-panel{width:min(380px,calc(100vw - 28px));height:520px;display:flex;flex-direction:column;min-width:0;overflow:hidden;background:#111212;border:1px solid #4b4638;box-shadow:0 20px 60px #000a}.assistant-panel header{display:flex;justify-content:space-between;align-items:start;min-width:0;padding:17px;border-bottom:1px solid #303130}.assistant-panel header div{min-width:0}.assistant-panel header span{display:block;color:#e8b84b;font-size:9px;letter-spacing:.1em}.assistant-panel header strong{font:600 16px 'Space Grotesk',sans-serif}.assistant-panel header button{flex:0 0 auto;border:0;background:transparent;color:#f2f0e9;font-size:26px;line-height:1}.assistant-feed{flex:1 1 auto;min-height:0;min-width:0;overflow-x:hidden;overflow-y:auto;padding:15px;display:flex;flex-direction:column;gap:10px;scrollbar-gutter:stable}.assistant-message{align-self:flex-start;box-sizing:border-box;min-width:0;max-width:88%;margin:0;padding:11px 12px;font:12px/1.55 Manrope,sans-serif;white-space:normal;overflow-wrap:anywhere;word-break:break-word;hyphens:auto}.assistant-message.assistant{background:#1c1d1c;border-left:2px solid #e8b84b;color:#d9d8d1}.assistant-message.user{align-self:flex-end;background:#e8b84b;color:#17150f}.assistant-message :deep(p){margin:0 0 10px}.assistant-message :deep(p:last-child){margin-bottom:0}.assistant-message :deep(h4){margin:0 0 8px;font:600 13px/1.35 'Space Grotesk',sans-serif}.assistant-message :deep(ul),.assistant-message :deep(ol){margin:7px 0;padding-left:18px}.assistant-message :deep(li){margin:3px 0;padding-left:1px}.assistant-message :deep(code){font:11px/1.45 'DM Mono',monospace;background:#0005;padding:1px 4px;overflow-wrap:anywhere}.assistant-message :deep(pre){max-width:100%;margin:8px 0;box-sizing:border-box;overflow-x:auto;overflow-y:hidden;background:#080909;padding:9px;white-space:pre}.assistant-message :deep(pre code){display:block;padding:0;background:transparent;overflow-wrap:normal;word-break:normal}.assistant-loading{font-style:italic;color:#aaa9a1}.quick-questions{flex:0 0 auto;min-width:0;padding:10px 14px;display:flex;gap:6px;overflow:auto;border-top:1px solid #303130}.quick-questions button{white-space:nowrap;background:transparent;border:1px solid #303130;color:#aaa9a1;padding:7px;font:9px 'DM Mono'}.quick-questions button:hover{color:#e8b84b;border-color:#e8b84b}.assistant-panel form{display:flex;flex:0 0 auto;min-width:0;padding:14px;gap:8px;border-top:1px solid #303130}.assistant-panel input{min-width:0;flex:1;background:#080909;border:1px solid #303130;color:#f2f0e9;padding:10px;font:12px Manrope,sans-serif}.assistant-panel form button{flex:0 0 40px;width:40px;border:0;background:#e8b84b;color:#17150f;font-size:18px}@media(max-width:560px){.assistant{right:14px;bottom:14px}.assistant-panel{height:min(520px,calc(100vh - 28px))}}
</style>
<style scoped>
.assistant-feed{width:100%;min-width:0;overflow-x:hidden}.assistant-message{position:static;min-width:0;max-width:88%;flex-shrink:1;overflow-wrap:anywhere;word-break:break-word}.assistant-message.bot{align-self:flex-start;background:#1c1d1c;border-left:2px solid #e8b84b;color:#d9d8d1}.quick-questions{width:100%;min-width:0;overflow:hidden;flex-wrap:wrap}.quick-questions button{min-width:0;max-width:100%;white-space:normal;overflow-wrap:anywhere}.assistant-panel form{width:100%;min-width:0;flex-direction:row;align-items:center}.assistant-panel form input{min-width:0;width:auto}.assistant-panel form button{flex:0 0 40px}
</style>
